// reconcileComponentReferences reconciles the referenced component descriptors and constructs a dependency tree out of them.
func (r *ComponentVersionReconciler) reconcileComponentReferences(ctx context.Context, parent *v1alpha1.ComponentVersion, references ocmdesc.References) ([]v1alpha1.Reference, error) {
	result := make([]v1alpha1.Reference, 0)
	for _, ref := range references {
		reference, err := r.reconcileComponentReference(ctx, parent, ref)
		if err != nil {
			return nil, fmt.Errorf("failed to reconcile reference: %w", err)
		}
		result = append(result, *reference)
	}
	return result, nil
}

func (r *ComponentVersionReconciler) reconcileComponentReference(ctx context.Context, parent *v1alpha1.ComponentVersion, ref ocmdesc.ComponentReference) (*v1alpha1.Reference, error) {
	// get component version
	rcv, err := r.OCMClient.GetComponentVersion(ctx, parent, ref.ComponentName, ref.Version)
	if err != nil {
		return nil, fmt.Errorf("failed to get component version: %w", err)
	}
	defer rcv.Close()

	// convert ComponentDescriptor to v3alpha1
	dv := &compdesc.DescriptorVersion{}
	cd, err := dv.ConvertFrom(rcv.GetDescriptor())
	if err != nil {
		return nil, fmt.Errorf("failed to convert component descriptor: %w", err)
	}

	descriptor, err := r.reconcileComponentDescriptorForReference(ctx, parent, ref, cd.(*compdesc.ComponentDescriptor))
	if err != nil {
		return nil, err
	}

	reference := referenceFromComponentDescriptor(ref, descriptor)
	if len(rcv.GetDescriptor().References) > 0 {
		out, err := r.reconcileComponentReferences(ctx, parent, rcv.GetDescriptor().References)
		if err != nil {
			return nil, err
		}
		reference.References = out
	}

	return &reference, nil
}

func (r *ComponentVersionReconciler) reconcileComponentDescriptorForReference(ctx context.Context, parent *v1alpha1.ComponentVersion, ref ocmdesc.ComponentReference, cd *compdesc.ComponentDescriptor) (*v1alpha1.ComponentDescriptor, error) {
	log := log.FromContext(ctx)

	// setup the component descriptor kubernetes resource
	componentName, err := r.constructComponentName(ref.ComponentName, ref.Version, ref.GetMeta().ExtraIdentity)
	if err != nil {
		return nil, fmt.Errorf("failed to generate name: %w", err)
	}
	descriptor := &v1alpha1.ComponentDescriptor{
		ObjectMeta: metav1.ObjectMeta{
			Namespace: parent.GetNamespace(),
			Name:      componentName,
		},
		Spec: v1alpha1.ComponentDescriptorSpec{
			ComponentVersionSpec: cd.Spec,
			Version:              ref.Version,
		},
	}

	if err := controllerutil.SetOwnerReference(parent, descriptor, r.Scheme); err != nil {
		return nil, fmt.Errorf("failed to set owner reference: %w", err)
	}

	// create or update the component descriptor kubernetes resource
	// we don't need to update it
	op, err := controllerutil.CreateOrUpdate(ctx, r.Client, descriptor, func() error {
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to create/update component descriptor: %w", err)
	}
	log.V(4).Info(fmt.Sprintf("%s(ed) descriptor", op), "descriptor", klog.KObj(descriptor))

	return descriptor, nil
}

func referenceFromComponentDescriptor(ref ocmdesc.ComponentReference, descriptor *v1alpha1.ComponentDescriptor) v1alpha1.Reference {
	return v1alpha1.Reference{
		Name:    ref.Name,
		Version: ref.Version,
		ComponentDescriptorRef: meta.NamespacedObjectReference{
			Name:      descriptor.Name,
			Namespace: descriptor.Namespace,
		},
		ExtraIdentity: ref.ExtraIdentity,
	}
}

