359: 		componentName string
360: 		version       string
361: 		identity      v1.Identity
362: 	}{
363: 		componentName: name,
364: 		version:       version,
365: 		identity:      identity,
366: 	}
367: 	h, err := hash.Hash(namingScheme, nil)
368: 	if err != nil {
369: 		return "", fmt.Errorf("failed to generate hash for name, version, identity: %w", err)
370: 	}
371: 	return fmt.Sprintf("%s-%s-%d", strings.ReplaceAll(name, "/", "-"), version, h), nil
